code_example:
class Widget {};
void logDeletion(Widget* w) { delete w; }

void run_example() {
    Widget* raw_ptr = new Widget();

    // DANGEROUS: Two shared_ptrs created from the same raw pointer.
    // Each creates its own control block and reference count.
    std::shared_ptr<Widget> spw1(raw_ptr, logDeletion);
    std::shared_ptr<Widget> spw2(raw_ptr, logDeletion); // UB! Second control block created.

    // When spw1 goes out of scope, it will delete raw_ptr.
    // When spw2 goes out of scope, it will delete raw_ptr AGAIN.
    // This leads to a double-free and undefined behavior.
}

// Correct way to share ownership
void correct_example() {
    std::shared_ptr<Widget> sp1(new Widget(), logDeletion);

    // CORRECT: Initialize the second shared_ptr from the first one.
    // This shares the control block and increments the reference count.
    std::shared_ptr<Widget> sp2 = sp1;

    // Both sp1 and sp2 now safely co-own the Widget.
}
